			search.base +
			encodeURI(
				'/3/search/movie?api_key=' +
					search.key +
					'&query=' +
					search.movie +
					( search.year !== null ? '&year=' + search.year : '' )
			)

		// Request
		var response = fetch( url, {
			method: 'GET'
		} )
			.then(
